  def lucide_icon(name, size: 18, css: nil)
    path = LUCIDE_PATHS.fetch(name.to_s)
    svg = %(<svg xmlns="http://www.w3.org/2000/svg" width="#{size}" height="#{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">#{path}</svg>)
    content_tag(:span, svg.html_safe, class: ["lucide-icon", css].compact.join(" "))
  end
